export default function CartaoProduto({ nome, preco }: {nome : string, preco : number}) {
    return (
        <div className="border border-gray-200 p-4 rounded-lg shadow-md max-w-sm">
            <h2 className="text-xl font-bold">{nome}</h2>
            <p className="text-marca font-semibold">{preco}</p>
            <button className="mt-3 bg-fundoEscuro text-fundoClaro px-4 py-2 rounded hover:bg-dourado-700 transition">
                Adicionar ao Carrinho
            </button>
        </div>
    );
}